INSERT INTO record_search (record_id, content, status, sensitivity, mention_policy, scope_type, scope_id, kind, valid_from, valid_until, primary_entity_id, updated_at) SELECT r.record_id, json_extract(v.payload_json, '$.payload'), r.status, r.sensitivity, r.mention_policy, r.scope_type, r.scope_id, r.kind, r.valid_from, r.valid_until, r.primary_entity_id, r.updated_at FROM records r JOIN record_revisions v ON v.record_id = r.record_id AND v.revision = r.current_revision
